export function flowerSVG(color = '#dca6ac', variant = 0) {
  const petals = Array.from({ length: variant % 2 ? 8 : 6 }, (_, i) => `<ellipse cx="50" cy="24" rx="${variant % 2 ? 8 : 11}" ry="20" transform="rotate(${i * (variant % 2 ? 45 : 60)} 50 43)" fill="${color}" opacity=".92"/>`).join('');
  return `<svg viewBox="0 0 100 280" preserveAspectRatio="none" aria-hidden="true"><path d="M50 280 Q38 183 50 43" fill="none" stroke="#759575" stroke-width="2.5"/><path d="M47 209 Q2 175 13 145 Q50 153 47 209M46 166 Q87 144 84 119 Q47 126 46 166" fill="#4f775b" stroke="#78966d" stroke-width=".7"/><path d="M47 210L19 157M47 167L79 128" stroke="#9aad794f" fill="none"/>${petals}<circle cx="50" cy="43" r="10" fill="#d9be77"/><circle cx="47" cy="40" r="3" fill="#f4dfac" opacity=".8"/></svg>`;
}
export function memorySVG(type) {
  const stars = Array.from({ length: 28 }, (_, i) => `<circle cx="${(i * 79 + 31) % 500}" cy="${(i * 47 + 23) % 220}" r="${i % 3 === 0 ? 1.5 : .8}" fill="#e8d7ac" opacity="${.25 + (i % 4) * .15}"/>`).join('');
  const scenes = {
    night: `<rect width="500" height="350" fill="#263c43"/>${stars}<circle cx="342" cy="88" r="31" fill="#e6d7af"/><path d="M0 258Q95 187 218 253T500 223V350H0" fill="#284b46"/><path d="M0 291Q105 250 248 281T500 252V350H0" fill="#1b3433"/><path d="M208 350L277 264 302 265 255 350" fill="#a6ad8d44"/><path d="M100 350V182M68 249L100 203 130 249M61 278L100 226 138 278" stroke="#152c2c" stroke-width="9" fill="#152c2c"/>`,
    icecream: `<rect width="500" height="350" fill="#514f4b"/><circle cx="388" cy="80" r="60" fill="#b5b49a" opacity=".15"/><path d="M0 258Q225 230 500 264V350H0" fill="#31483c"/><path d="M173 350L177 238M326 350L322 238" stroke="#9eab7e" stroke-width="3"/><path d="M173 284Q123 255 130 235Q170 241 173 284M326 297Q370 272 372 246Q331 253 326 297" fill="#718668"/><path d="M132 173L177 275 222 173M277 173L322 275 367 173" fill="#c79b71" stroke="#ddbe94" stroke-width="2"/><path d="M148 190L195 234M170 184L208 220M205 190L159 233M184 183L148 218M293 190L339 234M316 184L353 220M350 190L305 233M329 183L294 218" stroke="#9c795c" stroke-width="2"/><circle cx="159" cy="160" r="28" fill="#e3c5b4"/><circle cx="195" cy="160" r="28" fill="#d6afad"/><circle cx="177" cy="128" r="30" fill="#e6d9b8"/><circle cx="304" cy="160" r="28" fill="#a8b496"/><circle cx="340" cy="160" r="28" fill="#ddc9a5"/><circle cx="322" cy="128" r="30" fill="#caadb4"/><path d="M245 83C220 60 207 92 245 112C283 92 270 60 245 83" fill="#e3b4b1" opacity=".75"/>`,
    road: `<rect width="500" height="350" fill="#344b51"/>${stars}<circle cx="360" cy="74" r="32" fill="#e2cfaa"/><path d="M0 232Q80 148 201 224T500 202V350H0" fill="#4b6659"/><path d="M0 280Q159 189 277 248T500 246V350H0" fill="#253d35"/><path d="M184 350L265 216 274 216 350 350" fill="#878879"/><path d="M262 231L263 244M264 261L267 281M269 305L274 340" stroke="#e3d5aa" stroke-width="3"/><g fill="none" stroke="#172c29" stroke-width="7" stroke-linecap="round" stroke-linejoin="round"><circle cx="198" cy="306" r="23"/><circle cx="294" cy="306" r="23"/><path d="M198 306L222 270 261 301 198 306M222 270H267L294 306M261 301L278 260 272 250H259M219 266H236"/></g><path d="M231 267L248 247 266 256 256 277" stroke="#ddbab0" stroke-width="11" fill="none" stroke-linecap="round"/><circle cx="251" cy="232" r="12" fill="#e8d8b7"/><path d="M211 271L225 253 238 259" stroke="#a7b69a" stroke-width="11" fill="none" stroke-linecap="round"/><circle cx="227" cy="238" r="11" fill="#d5b8bd"/>`,
    flowers: `<rect width="500" height="350" fill="#5c6650"/><circle cx="381" cy="67" r="68" fill="#d5c59a" opacity=".16"/><path d="M0 350Q122 122 240 350M104 350Q282 163 427 350" fill="#384d3c"/>${Array.from({length:11},(_,i)=>{const x=30+i*44,y=160+(i*37)%130;return `<path d="M${x} 350Q${x-25} ${y+50} ${x} ${y}" stroke="#b7ba8b" stroke-width="3" fill="none"/><g transform="translate(${x} ${y})">${[0,60,120,180,240,300].map(a=>`<ellipse cy="-12" rx="8" ry="14" fill="${i%2?'#d7b6a7':'#dcd3ac'}" transform="rotate(${a})"/>`).join('')}<circle r="5" fill="#b89f5a"/></g>`;}).join('')}`
  };
  return `<svg viewBox="0 0 500 350" preserveAspectRatio="xMidYMid slice" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">${scenes[type] || scenes.night}</svg>`;
}
